using sv_994fd02c9a8f42c2bfbc067e73c10d57.Client.Models;
using sv_994fd02c9a8f42c2bfbc067e73c10d57.Client.Services;

namespace sv_994fd02c9a8f42c2bfbc067e73c10d57.Services;

public sealed class ShipmentService : IShipmentService
{
    private static readonly Dictionary<string, Shipment> Seeds = new(StringComparer.OrdinalIgnoreCase)
    {
        ["TRK-1001"] = new Shipment
        {
            TrackingNumber = "TRK-1001",
            Status = "In Transit",
            Location = "Memphis, TN",
            EstimatedDelivery = new DateTimeOffset(2026, 7, 5, 17, 0, 0, TimeSpan.Zero),
            StatusUpdates =
            [
                new StatusUpdate { Timestamp = new DateTimeOffset(2026, 6, 28, 9, 0, 0, TimeSpan.Zero), Status = "Picked Up", Location = "Los Angeles, CA" },
                new StatusUpdate { Timestamp = new DateTimeOffset(2026, 6, 29, 14, 30, 0, TimeSpan.Zero), Status = "In Transit", Location = "Phoenix, AZ" },
                new StatusUpdate { Timestamp = new DateTimeOffset(2026, 6, 30, 22, 15, 0, TimeSpan.Zero), Status = "In Transit", Location = "Memphis, TN" },
            ]
        },
        ["TRK-1002"] = new Shipment
        {
            TrackingNumber = "TRK-1002",
            Status = "Delivered",
            Location = "New York, NY",
            EstimatedDelivery = new DateTimeOffset(2026, 6, 30, 12, 0, 0, TimeSpan.Zero),
            StatusUpdates =
            [
                new StatusUpdate { Timestamp = new DateTimeOffset(2026, 6, 26, 8, 0, 0, TimeSpan.Zero), Status = "Picked Up", Location = "Chicago, IL" },
                new StatusUpdate { Timestamp = new DateTimeOffset(2026, 6, 27, 16, 0, 0, TimeSpan.Zero), Status = "In Transit", Location = "Columbus, OH" },
                new StatusUpdate { Timestamp = new DateTimeOffset(2026, 6, 28, 20, 45, 0, TimeSpan.Zero), Status = "Out for Delivery", Location = "New York, NY" },
                new StatusUpdate { Timestamp = new DateTimeOffset(2026, 6, 29, 10, 12, 0, TimeSpan.Zero), Status = "Delivered", Location = "New York, NY" },
            ]
        },
        ["TRK-1003"] = new Shipment
        {
            TrackingNumber = "TRK-1003",
            Status = "Processing",
            Location = "Seattle, WA",
            EstimatedDelivery = new DateTimeOffset(2026, 7, 8, 17, 0, 0, TimeSpan.Zero),
            StatusUpdates =
            [
                new StatusUpdate { Timestamp = new DateTimeOffset(2026, 6, 30, 15, 30, 0, TimeSpan.Zero), Status = "Label Created", Location = "Seattle, WA" },
                new StatusUpdate { Timestamp = new DateTimeOffset(2026, 7, 1, 0, 0, 0, TimeSpan.Zero), Status = "Processing", Location = "Seattle, WA" },
            ]
        },
    };

    public async Task<Shipment> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        await Task.Delay(1500, ct);

        if (!Seeds.TryGetValue(trackingNumber, out var shipment))
        {
            throw new KeyNotFoundException($"Shipment '{trackingNumber}' was not found.");
        }

        return shipment;
    }
}

@page "/shipments/{TrackingNumber}"
@rendermode InteractiveAuto
@using sv_994fd02c9a8f42c2bfbc067e73c10d57.Client.Models
@using sv_994fd02c9a8f42c2bfbc067e73c10d57.Client.Services
@inject IShipmentService ShipmentService
@inject ILogger<ShipmentTracker> Logger
@implements IDisposable

<PageTitle>Shipment @TrackingNumber</PageTitle>

<h1>Shipment Tracker</h1>

@if (_loading)
{
    <div class="alert alert-info" role="status">
        <span class="spinner-border spinner-border-sm me-2" aria-hidden="true"></span>
        Loading shipment <strong>@TrackingNumber</strong>&hellip;
    </div>
}
else if (_errorMessage is not null)
{
    <div class="alert alert-danger" role="alert">
        <p class="mb-2">@_errorMessage</p>
        <button class="btn btn-outline-danger btn-sm" @onclick="RetryAsync">Retry</button>
    </div>
}
else if (_shipment is not null)
{
    <div class="card mb-3">
        <div class="card-header">
            <strong>@_shipment.TrackingNumber</strong>
        </div>
        <div class="card-body">
            <dl class="row mb-0">
                <dt class="col-sm-4">Status</dt>
                <dd class="col-sm-8">@_shipment.Status</dd>

                <dt class="col-sm-4">Location</dt>
                <dd class="col-sm-8">@_shipment.Location</dd>

                <dt class="col-sm-4">Estimated Delivery</dt>
                <dd class="col-sm-8">
                    @(_shipment.EstimatedDelivery?.ToString("f") ?? "N/A")
                </dd>
            </dl>
        </div>
    </div>

    @if (_shipment.StatusUpdates.Count > 0)
    {
        <h2>Status History</h2>
        <table class="table table-striped">
            <thead>
                <tr>
                    <th>Timestamp</th>
                    <th>Status</th>
                    <th>Location</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var update in _shipment.StatusUpdates)
                {
                    <tr>
                        <td>@update.Timestamp.ToString("g")</td>
                        <td>@update.Status</td>
                        <td>@update.Location</td>
                    </tr>
                }
            </tbody>
        </table>
    }
}

@code {
    private CancellationTokenSource? _cts;
    private Shipment? _shipment;
    private string? _errorMessage;
    private bool _loading;
    private string? _loadedTrackingNumber;

    [Parameter]
    public string TrackingNumber { get; set; } = string.Empty;

    protected override async Task OnParametersSetAsync()
    {
        // Only reload when the tracking number actually changes.
        if (string.Equals(_loadedTrackingNumber, TrackingNumber, StringComparison.OrdinalIgnoreCase))
        {
            return;
        }

        await LoadShipmentAsync();
    }

    private async Task LoadShipmentAsync()
    {
        // Cancel any in-flight request before starting a new one.
        await CancelPendingRequestAsync();

        _loadedTrackingNumber = TrackingNumber;
        _shipment = null;
        _errorMessage = null;
        _loading = true;

        var cts = new CancellationTokenSource();
        _cts = cts;

        try
        {
            _shipment = await ShipmentService.GetShipmentAsync(TrackingNumber, cts.Token);
        }
        catch (OperationCanceledException) when (cts.Token.IsCancellationRequested)
        {
            // Request was intentionally cancelled — nothing to show.
            return;
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout fetching shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "The request timed out. Please check your connection and try again.";
        }
        catch (TaskCanceledException ex) when (ex.InnerException is TimeoutException)
        {
            Logger.LogError(ex, "HTTP timeout fetching shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "The request timed out. Please check your connection and try again.";
        }
        catch (KeyNotFoundException ex)
        {
            Logger.LogWarning(ex, "Shipment not found: {TrackingNumber}", TrackingNumber);
            _errorMessage = $"Shipment \"{TrackingNumber}\" was not found.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error fetching shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "Something went wrong while loading shipment details. Please try again.";
        }
        finally
        {
            _loading = false;
        }
    }

    private async Task RetryAsync()
    {
        _loadedTrackingNumber = null; // Force reload
        await LoadShipmentAsync();
    }

    private async Task CancelPendingRequestAsync()
    {
        if (_cts is not null)
        {
            await _cts.CancelAsync();
            _cts.Dispose();
            _cts = null;
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
    }
}

